import datetime
import re
from dataclasses import dataclass
from typing import Any, TypeVar, Callable, Type, cast
from uuid import UUID
import dateutil.parser


T = TypeVar("T")


def from_int(x: Any) -> int:
    assert isinstance(x, int) and not isinstance(x, bool)
    return x


def from_str(x: Any) -> str:
    assert isinstance(x, str)
    return x


def from_list(f: Callable[[Any], T], x: Any) -> list[T]:
    assert isinstance(x, list)
    return [f(y) for y in x]


def to_class(c: Type[T], x: Any) -> dict:
    assert isinstance(x, c)
    return cast(Any, x).to_dict()


def from_stringified_bool(x: str) -> bool:
    if x == "true":
        return True
    if x == "false":
        return False
    assert False


def from_date(x: Any) -> datetime.date:
    assert isinstance(x, str) and re.match(r"^\d{4}-\d{2}-\d{2}$", x)
    return dateutil.parser.parse(x).date()


def from_datetime(x: Any) -> datetime.datetime:
    return dateutil.parser.parse(x)


def from_none(x: Any) -> Any:
    assert x is None
    return x


def from_float(x: Any) -> float:
    assert isinstance(x, (float, int)) and not isinstance(x, bool)
    return float(x)


def from_bool(x: Any) -> bool:
    assert isinstance(x, bool)
    return x


def from_union(fs, x):
    for f in fs:
        try:
            return f(x)
        except:
            pass
    assert False


def is_type(t: Type[T], x: Any) -> T:
    assert isinstance(x, t)
    return x


def to_float(x: Any) -> float:
    assert isinstance(x, (int, float))
    return x


@dataclass
class MixedClass:
    a: int

    @staticmethod
    def from_dict(obj: Any) -> 'MixedClass':
        assert isinstance(obj, dict)
        a = from_int(obj["a"])
        return MixedClass(a)

    def to_dict(self) -> dict:
        result: dict = {}
        result["a"] = from_int(self.a)
        return result


@dataclass
class ListElement:
    v: int

    @staticmethod
    def from_dict(obj: Any) -> 'ListElement':
        assert isinstance(obj, dict)
        v = from_int(obj["v"])
        return ListElement(v)

    def to_dict(self) -> dict:
        result: dict = {}
        result["v"] = from_int(self.v)
        return result


@dataclass
class Nested:
    inner_name: str
    list: list[ListElement]

    @staticmethod
    def from_dict(obj: Any) -> 'Nested':
        assert isinstance(obj, dict)
        inner_name = from_str(obj["innerName"])
        list = from_list(ListElement.from_dict, obj["list"])
        return Nested(inner_name, list)

    def to_dict(self) -> dict:
        result: dict = {}
        result["innerName"] = from_str(self.inner_name)
        result["list"] = from_list(lambda x: to_class(ListElement, x), self.list)
        return result


@dataclass
class TopLevelElement:
    count: int
    flag: bool
    day: datetime.date
    at: str
    when: datetime.datetime
    id: UUID
    mixed: list[bool | float | MixedClass | list[int] | int | None]
    some_value: int | str
    nested: Nested
    top_level_class: int
    top_level_from_dict: int
    weird_key: int
    maybe: str | None = None
    maybe_count: int | None = None

    @staticmethod
    def from_dict(obj: Any) -> 'TopLevelElement':
        assert isinstance(obj, dict)
        count = int(from_str(obj["count"]))
        flag = from_stringified_bool(from_str(obj["flag"]))
        day = from_date(obj["day"])
        at = from_str(obj["at"])
        when = from_datetime(obj["when"])
        id = UUID(obj["id"])
        mixed = from_list(lambda x: from_union([from_none, from_float, from_bool, lambda x: int(from_str(x)), lambda x: from_list(from_int, x), MixedClass.from_dict], x), obj["mixed"])
        some_value = from_union([from_int, from_str], obj["someValue"])
        nested = Nested.from_dict(obj["nested"])
        top_level_class = from_int(obj["class"])
        top_level_from_dict = from_int(obj["from_dict"])
        weird_key = from_int(obj["Weird Key"])
        maybe = from_union([from_none, from_str], obj["maybe"])
        maybe_count = from_union([from_none, lambda x: int(from_str(x))], obj["maybeCount"])
        return TopLevelElement(count, flag, day, at, when, id, mixed, some_value, nested, top_level_class, top_level_from_dict, weird_key, maybe, maybe_count)

    def to_dict(self) -> dict:
        result: dict = {}
        result["count"] = from_str(str(self.count))
        result["flag"] = from_str(str(self.flag).lower())
        result["day"] = self.day.isoformat()
        result["at"] = from_str(self.at)
        result["when"] = self.when.isoformat()
        result["id"] = str(self.id)
        result["mixed"] = from_list(lambda x: from_union([lambda x: from_none((lambda x: is_type(type(None), x))(x)), lambda x: to_float((lambda x: is_type(float, x))(x)), lambda x: from_bool((lambda x: is_type(bool, x))(x)), lambda x: from_str((lambda x: str((lambda x: is_type(int, x))(x)))(x)), lambda x: from_list(from_int, (lambda x: is_type(list, x))(x)), lambda x: to_class(MixedClass, (lambda x: is_type(MixedClass, x))(x))], x), self.mixed)
        result["someValue"] = from_union([from_int, from_str], self.some_value)
        result["nested"] = to_class(Nested, self.nested)
        result["class"] = from_int(self.top_level_class)
        result["from_dict"] = from_int(self.top_level_from_dict)
        result["Weird Key"] = from_int(self.weird_key)
        result["maybe"] = from_union([from_none, from_str], self.maybe)
        result["maybeCount"] = from_union([lambda x: from_none((lambda x: is_type(type(None), x))(x)), lambda x: from_str((lambda x: str((lambda x: is_type(int, x))(x)))(x))], self.maybe_count)
        return result


