def top_level_from_dict(s: Any) -> list[TopLevelElement]:
    return from_list(TopLevelElement.from_dict, s)


def top_level_to_dict(x: list[TopLevelElement]) -> Any:
    return from_list(lambda x: to_class(TopLevelElement, x), x)


def counts_from_dict(s: Any) -> Counts:
    return Counts.from_dict(s)


def counts_to_dict(x: Counts) -> Any:
    return to_class(Counts, x)


def values_from_dict(s: Any) -> list[int | bool]:
    return from_list(lambda x: from_union([from_int, from_bool, lambda x: int(from_str(x))], x), s)


def values_to_dict(x: list[int | bool]) -> Any:
    return from_list(lambda x: from_union([lambda x: from_int((lambda x: is_type(int, x))(x)), lambda x: from_bool((lambda x: is_type(bool, x))(x))], x), x)

